test_assert(vfs_test_read_r(&r, -1, &value, 1) == -1 && r.error == EBADF,
            "negative descriptor accepted");
test_assert(vfs_test_write_r(&r, VFS_TEST_NEWLIB_FDS, "x", 1) == -1 &&
            r.error == EBADF, "large descriptor accepted");
