            vfsIOClose(&vfs_test_io_empty, 0) == CH_RET_EBADF &&
            vfsIODup(&vfs_test_io_empty, 0) == CH_RET_EBADF &&
            vfsIODup2(&vfs_test_io_empty, 0, 0) == CH_RET_EBADF &&
