test_assert(vfsIOInstall(&vfs_test_io, 2, &vfs_test_io_nodes[0].node) ==
            CH_RET_SUCCESS, "sparse installation failed");
test_assert(vfsIOInstall(&vfs_test_io, 2, &vfs_test_io_nodes[1].node) ==
