test_assert(vfsIOInstall(&vfs_test_io, -1, &vfs_test_io_nodes[1].node) ==
            CH_RET_EBADF &&
            vfsIOInstall(&vfs_test_io, 3, &vfs_test_io_nodes[1].node) ==
            CH_RET_EBADF, "out-of-range installation accepted");
