test_assert(vfsIOClose(&vfs_test_io, 0) == CH_RET_EBADF &&
            vfsIOClose(&vfs_test_io, -1) == CH_RET_EBADF &&
            vfsIOClose(&vfs_test_io, 3) == CH_RET_EBADF &&
            vfsIOGet(&vfs_test_io, 0) == NULL &&
            vfsIOGet(&vfs_test_io, -1) == NULL &&
